import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int h = nextInt(), w = nextInt();
        byte[] g = new byte[h * w];
        for (int i = 0; i < h; i++) {
            String row = next();
            for (int j = 0; j < w; j++) g[i * w + j] = (byte) row.charAt(j);
        }
        int[] dist = new int[h * w], q = new int[h * w];
        Arrays.fill(dist, -1);
        dist[0] = 0;
        int head = 0, tail = 0;
        q[tail++] = 0;
        while (head < tail) {
            int cell = q[head++];
            if (g[cell] == '9') {
                System.out.println(dist[cell]);
                return;
            }
            int r = cell / w, c = cell % w;
            int[] nxt = {r > 0 ? cell - w : -1, r + 1 < h ? cell + w : -1, c > 0 ? cell - 1 : -1, c + 1 < w ? cell + 1 : -1};
            for (int v : nxt) {
                if (v >= 0 && g[v] != '0' && dist[v] < 0) {
                    dist[v] = dist[cell] + 1;
