            }
        }
        System.out.println(-1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	h, w := nextInt(), nextInt()
	g := make([]byte, 0, h*w)
	for i := 0; i < h; i++ {
		g = append(g, token()...)
	}
	dist := make([]int32, h*w)
	for i := range dist {
		dist[i] = -1
	}
	dist[0] = 0
	q := make([]int32, 0, h*w)
	q = append(q, 0)
	for head := 0; head < len(q); head++ {
		cell := int(q[head])
		if g[cell] == '9' {
			fmt.Println(dist[cell])
			return
		}
		r, c := cell/w, cell%w
		nxt := [4]int{-1, -1, -1, -1}
		if r > 0 {
			nxt[0] = cell - w
		}
		if r+1 < h {
			nxt[1] = cell + w
		}
		if c > 0 {
			nxt[2] = cell - 1
		}
		if c+1 < w {
			nxt[3] = cell + 1
		}
		for _, v := range nxt {
			if v >= 0 && g[v] != '0' && dist[v] < 0 {
				dist[v] = dist[cell] + 1
				q = append(q, int32(v))
			}
		}
	}
	fmt.Println(-1)
}
